function minPathSum(grid: number[][]): number {
  const m = grid.length;
  const n = grid[0].length;
  // dp[j] — минимальная сумма пути до клетки (i, j) текущей строки.
  // Перед обновлением dp[j] хранит значение «сверху» (строка i - 1).
  const dp: number[] = new Array(n).fill(Infinity);

  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (i === 0 && j === 0) {
        // Стартовая клетка
        dp[j] = grid[0][0];
        continue;
      }
      // Сверху — старое dp[j], слева — уже обновлённое dp[j - 1].
      // За границей сетки — Infinity, такой ход невозможен.
      const up = dp[j];
      const left = j > 0 ? dp[j - 1] : Infinity;
      dp[j] = grid[i][j] + Math.min(up, left);
    }
  }

  // Правый нижний угол
  return dp[n - 1];
}

// Время: O(m · n) — каждая клетка один раз
// Память: O(n) — одна строка dp
